{
  "name": "@opencode-cockpit/subagents",
  "version": "0.11.2",
  "description": "See what your subagents are doing: in the sidebar, full screen, and message them",
  "type": "module",
  "license": "MIT",
  "author": "Codestz",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Codestz/opencode-cockpit.git",
    "directory": "packages/subagents"
  },
  "homepage": "https://cockpit.codestz.dev/subagents/overview/",
  "bugs": {
    "url": "https://github.com/Codestz/opencode-cockpit/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "subagents",
    "agents",
    "tui",
    "terminal"
  ],
  "exports": {
    "./server": {
      "types": "./types/server.d.ts",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./types/tui/index.d.ts",
      "default": "./dist/tui/index.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0",
    "bun": ">=1.3.5"
  },
  "files": [
    "server.js",
    "tui.js",
    "dist",
    "types",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-cockpit/client": "0.11.2",
    "@opencode-ai/plugin": "1.18.33"
  },
  "devDependencies": {
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "bin": {
    "opencode-subagents": "./dist/cli/preview.js",
    "subagents": "./dist/cli/preview.js"
  }
}
